test_setup_files.tests/limiter_test.rs:
use token_bucket::TokenBucket;

#[test]
fn starts_full_and_drains() {
    let mut b = TokenBucket::new(3.0, 1.0);
    assert!(b.allow(0.0));
    assert!(b.allow(0.0));
    assert!(b.allow(0.0));
    assert!(!b.allow(0.0));
}

#[test]
fn refills_over_time() {
    let mut b = TokenBucket::new(3.0, 1.0);
    for _ in 0..3 { b.allow(0.0); }
    assert!(!b.allow(0.5));
    assert!(b.allow(1.0));
    assert!(!b.allow(1.0));
}

#[test]
fn refill_caps_at_capacity() {
    let mut b = TokenBucket::new(2.0, 1.0);
    b.allow(0.0);
    b.allow(0.0);
    assert!(b.allow(1000.0));
    assert!(b.allow(1000.0));
    assert!(!b.allow(1000.0));
}

